func TestReportFindsWrappedStatusCoder(t *testing.T) {
	var buf bytes.Buffer
	prevOut, prevExit := Out, exitFunc
	defer func() { Out, exitFunc = prevOut, prevExit }()
	Out = &buf
	code := -1
	exitFunc = func(c int) { code = c }

	Report(fmt.Errorf("loading config: %w", NewCode("boom", 3)))

	if code != 3 {
		t.Fatalf("exit code = %d, want 3", code)
	}
	if buf.String() != "boom\n" {
		t.Fatalf("output = %q, want %q", buf.String(), "boom\n")
	}
}
